# lerp :: (0.0, 10.0, 0.0)
def lerp(a, b, t):
    return a + (b - a) * t

if __name__ == '__main__':
    print(lerp((0.0, 10.0, 0.0)))

# lerp :: (0.0, 10.0, 0.5)
def lerp(a, b, t):
    return a + (b - a) * t

if __name__ == '__main__':
    print(lerp((0.0, 10.0, 0.5)))

# lerp :: (0.0, 10.0, 1.0)
def lerp(a, b, t):
    return a + (b - a) * t

if __name__ == '__main__':
    print(lerp((0.0, 10.0, 1.0)))
